+    block.querySelector(".asst-copy").addEventListener("click", async () => {
+      const ok = await copyToClipboard(String(msg.content || ""));
+      if (ok) {
+        const b = block.querySelector(".asst-copy");
+        b.classList.add("copied");
+        b.innerHTML = SVG_CHECK;
