+
+/**
+ * Smooth typewriter renderer — drains an incoming char buffer at a constant
+ * rate (≈35 chars/sec) so the assistant reply appears to *type itself* live,
+ * ChatGPT-style, instead of popping in at whatever irregular chunk sizes the
+ * upstream sends. Each newly-typed slice gets a short fade-in via the
+ * `.stream-fresh` span so the growth reads as buttery-soft, not staccato.
+ *
+ *   feed(text)  → append to internal buffer, start the loop if idle
+ *   flush()     → drain everything immediately (called at `done`)
+ *   stop()      → cancel the loop (called on abort / cleanup)
+ *   getRendered()→ current on-screen text (for saving to state)
+ */
+function createSmoothTyper(contentEl, opts = {}) {
+  const charsPerSecond = opts.charsPerSecond || 35;
+  let buffer = "";        // pending chars waiting to be typed
+  let rendered = "";      // chars already committed to the DOM
+  let rafId = null;
+  let lastTs = 0;
+  let carry = 0;          // fractional-char accumulator (for sub-frame accuracy)
+  let finished = false;
+
+  function paint(freshTail) {
+    // Render the whole accumulated text as markdown, then append a small
+    // "fresh" span that carries only the very last slice so it can fade in
+    // softly on top of the already-settled prefix. A blinking cursor at the
+    // end keeps the ChatGPT feel.
+    const safeMain = renderMarkdown(rendered.slice(0, rendered.length - freshTail.length));
+    const safeFresh = renderMarkdown(freshTail);
+    // Strip trailing <p> wrapping if the fresh tail is tiny — we want the
+    // fade span to sit inline, not on its own line.
+    const inlineFresh = safeFresh.replace(/^<p>([\s\S]*)<\/p>\s*$/, "$1");
+    contentEl.innerHTML =
+      safeMain +
+      `<span class="stream-fresh">${inlineFresh}</span>` +
+      `<span class="cursor-blink"></span>`;
+  }
+
+  function tick(ts) {
+    if (!lastTs) lastTs = ts;
+    const dt = (ts - lastTs) / 1000;
+    lastTs = ts;
+    carry += dt * charsPerSecond;
+    let toEmit = Math.floor(carry);
+    if (toEmit > 0 && buffer.length > 0) {
+      // If the buffer is growing faster than we can drain (e.g. long backlog
+      // after tool call), gently speed up so we never lag more than ~500ms
+      // behind. This keeps things tight without ruining the smooth feel.
+      if (buffer.length > charsPerSecond * 0.8) {
+        toEmit = Math.min(buffer.length, toEmit + Math.ceil(buffer.length * 0.05));
+      }
+      const slice = buffer.slice(0, toEmit);
+      buffer = buffer.slice(toEmit);
+      rendered += slice;
+      carry -= toEmit;
+      // The "fresh" tail is the last ~12 chars — small enough to fade nicely,
+      // big enough to feel alive.
+      const tailLen = Math.min(rendered.length, 12);
+      paint(rendered.slice(rendered.length - tailLen));
+      scrollToBottom();
+    }
+    if (buffer.length > 0) {
+      rafId = requestAnimationFrame(tick);
+    } else {
+      rafId = null;
+      lastTs = 0;
+      if (finished) {
+        // Nothing more will come — settle the DOM cleanly (no fresh span).
+        contentEl.innerHTML = renderMarkdown(rendered) + '<span class="cursor-blink"></span>';
+      }
+    }
+  }
+
+  return {
+    feed(text) {
+      if (!text) return;
+      buffer += text;
+      if (rafId == null) {
+        lastTs = 0;
+        rafId = requestAnimationFrame(tick);
+      }
+    },
+    flush() {
+      // Drain everything right now — used on the `done` event so we don't
+      // leave the last few chars unwritten after the stream ends.
+      if (buffer.length) {
+        rendered += buffer;
+        buffer = "";
+      }
+      if (rafId != null) { cancelAnimationFrame(rafId); rafId = null; }
+      contentEl.innerHTML = renderMarkdown(rendered);
+    },
+    stop() {
+      if (rafId != null) { cancelAnimationFrame(rafId); rafId = null; }
+    },
+    finish() {
+      finished = true;
+      // Kick the loop one more time so it can settle if the buffer is empty.
+      if (rafId == null) {
+        lastTs = 0;
+        rafId = requestAnimationFrame(tick);
+      }
+    },
+    getRendered() { return rendered + buffer; },
+  };
+}
+
+/**
+ * Streams a fresh assistant reply. Rebuilds the api-messages array from
+ * state.messages every call — this is critical: a stale, growing apiMessages
+ * was the reason the second message never rendered in v2.0.
+ */
+async function streamAssistantResponse() {
+  const asstMsg = { role: "assistant", content: "", tool_events: [], generated_images: [] };
+  state.messages.push(asstMsg);
+  const asstIndex = state.messages.length - 1;
+  const asstBlock = renderMessage(asstMsg, asstIndex);
+  const contentEl = asstBlock.querySelector(".assistant-content");
+  const strip = asstBlock.querySelector(".tool-strip");
+  const bodyEl = asstBlock.querySelector(".message-body");
+
+  const thinking = document.createElement("div");
+  thinking.className = "thinking";
+  thinking.innerHTML = `<span>${t("thinking")}</span><span class="dots"><span></span><span></span><span></span></span> <span class="elapsed" style="font-size:11px;opacity:.6">0.0s</span>`;
+  bodyEl.insertBefore(thinking, contentEl);
+  const elapsedEl = thinking.querySelector(".elapsed");
+  const startTime = Date.now();
+  const timer = setInterval(() => {
+    elapsedEl.textContent = ((Date.now() - startTime) / 1000).toFixed(1) + "s";
+  }, 100);
+  const removeThinking = () => {
+    if (thinking && thinking.parentElement) thinking.remove();
+    clearInterval(timer);
+  };
+
+  state.streaming = true;
+  updateSendBtn();
+  state.abortController = new AbortController();
+
+  // Build clean API messages from state (excluding the trailing in-progress assistant).
+  //
+  // Critical fix (v2.2): previously we dropped assistant turns that had no text
+  // (e.g. the model only called a tool then died mid-turn). That left orphan
+  // `user`->`user` sequences in the transcript, which is the root cause of the
+  // "some messages get no answer" bug reported by users. We now substitute a
+  // placeholder assistant reply when the previous turn ended without any text,
+  // so every user turn is properly paired with an assistant turn.
+  const apiMessages = [];
+  const attachedImageIds = [];
+  // v2.5 fix: `lastUserIdx` finds the MOST RECENT user turn — the only one whose
+  // images should ride along on this request. Previously we attached image_ids
+  // from *any* prior user turn that happened to carry them, so an image the
+  // user attached three messages ago kept getting re-sent on every follow-up
+  // — the upstream then rejected the oversized payload and the model reported
+  // "I didn't receive an image". Now: attach ONLY the images the current turn
+  // carries. If the current user turn has no images, nothing is attached.
+  const lastUserIdx = (() => {
+    for (let i = state.messages.length - 1; i >= 0; i--) {
+      if (i === asstIndex) continue;
+      if (state.messages[i].role === "user") return i;
+    }
+    return -1;
+  })();
+  let lastPushedRole = null;
+  for (let i = 0; i < state.messages.length; i++) {
+    const m = state.messages[i];
+    if (i === asstIndex) continue;                       // skip in-progress assistant
+    if (m.role === "user") {
+      // If the previous message we pushed was also a user, insert a stub assistant
+      // reply to keep strict user/assistant alternation for the upstream model.
+      if (lastPushedRole === "user") {
+        apiMessages.push({ role: "assistant", content: "(ok)" });
+      }
+      apiMessages.push({ role: "user", content: m.content });
+      lastPushedRole = "user";
+      // Only the MOST RECENT user message attaches images — and only if that
+      // exact message is the one currently being sent (i.e. has image_ids AND
+      // it's the last user turn in the transcript).
+      if (i === lastUserIdx && Array.isArray(m.image_ids) && m.image_ids.length) {
+        attachedImageIds.push(...m.image_ids);
+      }
+    } else if (m.role === "assistant") {
+      if (m.content) {
+        apiMessages.push({ role: "assistant", content: m.content });
+        lastPushedRole = "assistant";
+      } else if (lastPushedRole === "user") {
+        // Empty assistant (tool-only turn) — emit a minimal placeholder so the
+        // strict-alternation invariant holds. Without this the next user turn
+        // would be silently dropped by strict backends.
+        apiMessages.push({ role: "assistant", content: "(tool call only)" });
+        lastPushedRole = "assistant";
+      }
+    }
+  }
+
+  let accumulated = "";
+  let errored = false;
+  let gotAnything = false;
+  let typer = null;  // lazy — only created once the first delta arrives
+
+  try {
+    const res = await fetch("/api/chat/stream", {
+      method: "POST",
+      headers: authHeaders({ "Content-Type": "application/json" }),
+      body: JSON.stringify({
+        messages: apiMessages,
+        chat_id: state.chatId,
+        model: state.currentModel,
+        mode: state.currentMode,
+        attached_images: attachedImageIds,
+        agent_mode: state.agentMode || "normal",
+        agent_id: state.selectedAgentId || null,
+      }),
+      signal: state.abortController.signal,
+    });
+    if (!res.ok || !res.body) {
+      let detail = "HTTP " + res.status;
+      try { const j = await res.json(); detail = j.detail || detail; } catch {}
+      throw new Error(detail);
+    }
+
+    const reader = res.body.getReader();
+    const decoder = new TextDecoder();
+    let buffer = "";
+    while (true) {
+      const { value, done } = await reader.read();
+      if (done) break;
+      buffer += decoder.decode(value, { stream: true });
+      const events = buffer.split("\n\n");
+      buffer = events.pop() || "";
+      for (const rawEvent of events) {
+        const lines = rawEvent.split("\n");
+        let eventName = "message", dataStr = "";
+        for (const line of lines) {
+          if (line.startsWith("event:")) eventName = line.slice(6).trim();
+          else if (line.startsWith("data:")) dataStr += line.slice(5).trim();
+        }
+        if (!dataStr) continue;
+        let data;
+        try { data = JSON.parse(dataStr); } catch { continue; }
+
+        if (eventName === "thinking") {
+          // heartbeat from server; keep the indicator alive
+          gotAnything = true;
+        } else if (eventName === "delta") {
+          gotAnything = true;
+          removeThinking();
+          accumulated += data.content;
+          // Feed the smooth typer instead of instantly re-rendering. This turns
+          // chunky server bursts into a steady, ChatGPT-style live typing feel.
+          if (!typer) typer = createSmoothTyper(contentEl, { charsPerSecond: 35 });
+          typer.feed(data.content);
+        } else if (eventName === "tool_call") {
+          gotAnything = true;
+          removeThinking();
+          const notice = document.createElement("div");
+          notice.className = "tool-notice";
+          notice.dataset.callId = data.id;
+          notice.innerHTML = `<span class="spinner"></span> ${toolLabel(data.name)} <em>${escapeHtml(shortenArgs(data.name, data.args))}</em>${data.duplicate ? ' <span class="dup-badge">dup</span>' : ''}`;
+          strip.appendChild(notice);
+          asstMsg.tool_events.push({ name: data.name, args: data.args, id: data.id, summary: shortenArgs(data.name, data.args) });
+        } else if (eventName === "tool_result") {
+          const notice = strip.querySelector(`[data-call-id="${data.id}"]`);
+          if (notice) {
+            notice.classList.add("done");
+            const spinner = notice.querySelector(".spinner");
+            if (spinner) spinner.outerHTML = `<span class="check">✓</span>`;
+          }
+        } else if (eventName === "image_generated") {
+          gotAnything = true;
+          removeThinking();
+          const imgEl = mountGeneratedImage(strip, data.url, data.prompt || "");
+          asstMsg.generated_images.push({ url: data.url, prompt: data.prompt });
+        } else if (eventName === "done") {
+          gotAnything = true;
+          removeThinking();
+          // Let the typer drain whatever's still queued in its buffer, then
+          // settle the DOM (drops the cursor + fresh span, re-enhances code).
+          if (typer) { typer.finish(); }
+          // Give the typer a moment to visually catch up before final polish.
+          await new Promise((r) => setTimeout(r, 40));
+          if (typer) { typer.flush(); }
+          contentEl.innerHTML = renderMarkdown(accumulated);
+          enhanceCodeBlocks(contentEl);
+        } else if (eventName === "error") {
+          removeThinking();
+          errored = true;
+          const err = document.createElement("div");
+          err.className = "tool-notice error";
+          err.textContent = "⚠ " + data.message;
+          strip.appendChild(err);
+        }
+        scrollToBottom();
+      }
+    }
+  } catch (err) {
+    if (err.name !== "AbortError") {
+      errored = true;
+      const errEl = document.createElement("div");
+      errEl.className = "tool-notice error";
+      errEl.textContent = "⚠ " + err.message;
+      strip.appendChild(errEl);
+    }
+  } finally {
+    removeThinking();
+    // Make sure the typewriter is fully drained and torn down before we
+    // touch the DOM — otherwise a stray requestAnimationFrame could rewrite
+    // contentEl.innerHTML *after* enhanceCodeBlocks(), killing copy buttons.
+    if (typer) { typer.flush(); typer.stop(); }
+    state.streaming = false;
+    state.abortController = null;
+    updateSendBtn();
+    asstMsg.content = accumulated;
+    if (!gotAnything && !errored) {
+      // Nothing came back and no error — remove the empty assistant slot
+      state.messages.pop();
+      asstBlock.remove();
+    } else if (!accumulated && !asstMsg.generated_images.length && !errored) {
+      // Model called tools but ended without a text answer. Add a subtle marker so the bubble isn't blank.
+      contentEl.innerHTML = `<em style="color:var(--text-dim)">${t("emptyReply")}</em>`;
+    } else {
+      // Finalise codeblocks post-stream
+      contentEl.innerHTML = renderMarkdown(accumulated);
+      enhanceCodeBlocks(contentEl);
+    }
+    await saveChat();
+  }
+}
+
+function shortenArgs(name, args) {
+  args = args || {};
+  if (name === "web_search") return args.query || "";
+  if (name === "run_code") return (args.language || "code") + " • " + String(args.code || "").split("\n")[0].slice(0, 60);
+  if (name === "generate_image") return String(args.prompt || "").slice(0, 80);
+  if (name === "analyze_image") return String(args.question || "").slice(0, 80);
+  return JSON.stringify(args).slice(0, 80);
+}
+
+function updateSendBtn() {
+  const btn = el("sendBtn");
+  if (state.streaming) {
