+          <div class="agent-opt-desc">${escapeHtml(a.description_en || a.description || "")}</div>
+        </div>
+        <span class="agent-opt-dot" style="background:${a.color || "#7c9cff"}"></span>`;
+      opt.addEventListener("click", () => selectAgent(a.id));
